    public static void solve() {
        int n = in.nextInt();
        double target = in.nextDouble();

        int lo = 0, hi = n - 1;
        while (lo < hi) {
            int mid = lo + ((hi - lo) >>> 1);
            double prob = computeProbability(mid, n);
            if (prob >= target) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
