    private static double computeProbability(int m, int n) {
        long totalWays = nC3(n);
        double favorable = 0.0;
        favorable += nC3(m);
        favorable += (double) nC2(m) * (n - m);
        favorable += 0.5 * (double) m * nC2(n - m);
        return favorable / totalWays;
    }

    private static long nC3(int n) {
        if (n < 3) return 0;
        return (long) n * (n - 1) * (n - 2) / 6;
    }

    private static long nC2(int n) {
        if (n < 2) return 0;
        return (long) n * (n - 1) / 2;
