    static long pow(long base, long exp) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res *= base;
            base *= base;
            exp >>= 1;
        }
        return res;
    }

    static long modInverse(long a, int mod) {
        return modPow(a, mod - 2, mod);
