class Pair {
    int i, j;
    Pair(int i, int j) { this.i = i; this.j = j; }
    @Override public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        Pair p = (Pair) o;
        return i == p.i && j == p.j;
    }
    @Override public int hashCode() { return Objects.hash(i, j); }
}

class FastReader {
    BufferedReader br;
    StringTokenizer st;
    public FastReader() { br = new BufferedReader(new InputStreamReader(System.in)); }
    String next() {
        while (st == null || !st.hasMoreElements()) {
            try { st = new StringTokenizer(br.readLine()); } catch (IOException e) { e.printStackTrace(); }
        }
        return st.nextToken();
    }
    int nextInt() { return Integer.parseInt(next()); }
    long nextLong() { return Long.parseLong(next()); }
    double nextDouble() { return Double.parseDouble(next()); }
    String nextLine() {
        try { return br.readLine(); } catch (IOException e) { return ""; }
    }
}

class Node {
    int data, open, close;
    Node() { this(0, 0, 0); }
    Node(int data, int open, int close) { this.data = data; this.open = open; this.close = close; }
}

class SegmentTree {
    int n;
    Node[] tree;
    SegmentTree(int n) { this.n = n; tree = new Node[4 * (Integer.highestOneBit(n) << 1)]; }
    void build(Node[] nodes) { build(0, 0, n - 1, nodes); }
    private void build(int idx, int l, int r, Node[] nodes) {
        if (l == r) { tree[idx] = nodes[l]; return; }
        int mid = (l + r) >>> 1;
        build((idx << 1) + 1, l, mid, nodes);
        build((idx << 1) + 2, mid + 1, r, nodes);
        tree[idx] = combine(tree[(idx << 1) + 1], tree[(idx << 1) + 2]);
    }
    void update(int pos, Node node) { update(0, 0, n - 1, pos, node); }
    private void update(int idx, int l, int r, int pos, Node node) {
        if (pos < l || r < pos) return;
        if (l == r) { tree[idx] = node; return; }
        int mid = (l + r) >>> 1;
        update((idx << 1) + 1, l, mid, pos, node);
        update((idx << 1) + 2, mid + 1, r, pos, node);
        tree[idx] = combine(tree[(idx << 1) + 1], tree[(idx << 1) + 2]);
    }
    Node rangeQuery(int ql, int qr) { return rangeQuery(0, 0, n - 1, ql, qr); }
    private Node rangeQuery(int idx, int l, int r, int ql, int qr) {
        if (qr < l || ql > r) return new Node();
        if (ql <= l && r <= qr) return tree[idx];
        int mid = (l + r) >>> 1;
        return combine(rangeQuery((idx << 1) + 1, l, mid, ql, qr), rangeQuery((idx << 1) + 2, mid + 1, r, ql, qr));
    }
    Node combine(Node a, Node b) {
        if (a == null) return b;
        if (b == null) return a;
        int overlap = Math.min(a.open, b.close);
        return new Node(a.data + b.data + 2 * overlap, a.open + b.open - overlap, a.close + b.close - overlap);
    }
}
